import java.util.*; class RandomizedCollection { private List<Integer> list; private Map<Integer, LinkedHashSet<Integer>> map; private Random rand; public RandomizedCollection() { list = new ArrayList<>(); map = new HashMap<>(); rand = new Random(); } public boolean insert(int val) { boolean exists = map.containsKey(val); if (!exists) { map.put(val, new LinkedHashSet<>()); } map.get(val).add(list.size()); list.add(val); return !exists; } public boolean remove(int val) { if (!map.containsKey(val) || map.get(val).isEmpty()) { return false; } int lastVal = list.get(list.size() - 1); int indexToRemove = map.get(val).iterator().next(); map.get(val).remove(indexToRemove); if (indexToRemove < list.size() - 1) { list.set(indexToRemove, lastVal); map.get(lastVal).remove(list.size() - 1); map.get(lastVal).add(indexToRemove); } list.remove(list.size() - 1); if (map.get(val).isEmpty()) { map.remove(val); } return true; } public int getRandom() { return list.get(rand.nextInt(list.size())); } }